from pathlib import Path
p=Path('src/utils.ts')
s=p.read_text().replace('if (input.startsWith(_base)) {','if (hasBase(input, _base)) {',1).replace('if ("'!input.startsWith(_base)) {'"','if ("'!hasBase(input, _base)) {'"',1)
pos=s.index('/**\\n * Add/Replace the query')
s=s[:pos]+'''function hasBase(input: string, base: string): boolean {
  if ("'!input.startsWith(base)) {
    return false;
  }
  const next = input[base.length];
  return next === undefined || next === "/" || next === "?" || next === "#";
}

'"'''+s[pos:]
p.write_text(s)
p=Path('test/base.test.ts')
s=p.read_text()+'''
describe(\"base path boundaries\", () => {
  for (const base of [\"/admin\", \"/admin/\"]) {
    for (const input of [\"/admin-dashboard\", \"/administrator\", \"/admin%2Fdashboard\"]) {
      test("'`${base} does not match ${input}`, () => {
        expect(withoutBase(input, base)).toBe(input);
        expect(withBase(input, base)).toBe(`/admin${input}`);
      });
    }

    for (const suffix of ["", "/", "/dashboard", "?x", "#section", "?x#section"]) {
      test(`${base} matches /admin${suffix}`, () => {
        const input = `/admin${suffix}`;
        expect(withoutBase(input, base)).toBe(
          suffix.startsWith("/") ? suffix : `/${suffix}`,
        );
        expect(withBase(input, base)).toBe(input);
      });
    }
  }
});
'"'''
p.write_text(s)
PY
pnpm test"

